  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('Sri Ramcharitmanas Satsang 2026', 'April 11-15, 2026', 'Joined Hands with Hanumant Seva Trust to organise a 5 day Sundarkand and Ramcharitmanas program with Shri Dhaval Kumar ji. Completely free event for members and their family and friends. Attended by over 100 Kutumbians.', 'A very spiritual and devotional atmosphere, great sessions on ram bhakts like Hanuman ji, Kewat Ji, nice prasadam on each day') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '26satsang1.jpeg', 0);
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '26satsang2.jpeg', 1);
