  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('Kutumb Yoga Picnic 2025', 'December 7, 2025', 'Bring your health questions and discover insights on well-being through yoga and home remedies. Over 100 participants joined us for a special yoga picnic and get together session in the park.', 'A meaningful yoga and home remedies session, favourite home cooked dish to share, peaceful atmosphere') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25yogapicnic1.jpeg', 0);
