  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('Kutumb Pariwar Diwali Party 2025', 'October 26, 2025', 'Our biggest event of the year brought together over 300 community members for a day of celebration, cultural performances, food, and fun. The festival showcased the diversity and unity of our community.', 'Event featured cultural dances, food stalls, kids activities, and community performances') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25diwali2.jpeg', 0);
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25diwali3.jpeg', 1);
