  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'video', '25diwalivideo.mp4', 3);
  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('International Yoga Day 2025', 'June 21, 2025', 'Over 100 participants joined us for a special yoga session in the park to celebrate International Yoga Day. The session focused on unity, wellness, and community bonding.', 'Large group yoga session in community hall, diverse participants, peaceful atmosphere') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25intyoga1.jpeg', 0);
