  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('Kutumb Holi Celebration 2025', 'March 16, 2025', 'Joined Hands with Darpan Radio to organise a Community Holi Celebration. Completely free event for members and their family and friends. Attended by over 100 Kutumbians including kids. Lots of Masti with singing and dancing; and traditional Holi sweets and savouries.', 'Volunteers preparing meals, distribution to community members, smiling faces') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25holi1.jpeg', 0);
