  INSERT INTO kutumb_past_events (title, date_text, description, highlights) VALUES ('Kutumb NewYear SundarkandPath 2025', 'January 1, 2025', 'Event for members and their family and friends. For a perfect and devotional start of the year. Joined hands with our own Nand and Rajni Upadhyay by sponsoring the hall rental.', 'Large group session in Kutumb house, devotional atmosphere, vegetarian bhojan prasad') RETURNING id INTO new_id;
  INSERT INTO kutumb_past_event_media (past_event_id, type, src, sort_order) VALUES (new_id, 'image', '25sunderkand1.jpeg', 0);
