INSERT INTO kutumb_activities (title, image1, image2, description, schedule, participation_options, online_yoga, in_person_yoga, benefits, sort_order) VALUES ('Kutumb Yoga', 'yoga.jpeg', 'online-yoga.jpeg', 'Regular yoga sessions promoting physical wellness, mental clarity, and strong community bonding. Suitable for all levels.', 'Daily on Zoom (5:30 AM - 6:45 AM) + in-person sessions at parks.', ARRAY['Online (Zoom)','In-Person - The Ponds Park','In-Person - Kellyville North Park','In-Person - The Gables']::TEXT[], ARRAY['Regular Zoom yoga on all days catering for Australian and Indian yogis','Over 250 members in WhatsApp Yoga Group','Dedicated Australian yoga teachers from Kutumb family','Under the guidance of Shri Arun Srivastav (Resident Expert & Yoga Guru)']::TEXT[], ARRAY['Continuing summer in-person yoga in The Ponds and Kellyville North parks','New location started at The Gables','Run by dedicated and passionate yoga teachers','Becoming very popular with locals']::TEXT[], ARRAY['Improve flexibility and strength','Reduce stress and anxiety','Connect with like-minded individuals','Free for all community members']::TEXT[], 0);
INSERT INTO kutumb_activities (title, image1, image2, description, schedule, participation_options, online_yoga, in_person_yoga, benefits, sort_order) VALUES ('Kutumb Food Distribution', 'food-service.jpeg', NULL, 'Our food distribution program serves nutritious meals to those in need within our community, like international students at Western Sydney University.', 'Every Saturday, 12:00 PM - 3:00 PM', ARRAY['Volunteer - Food Preparation','Volunteer - Distribution','Recipient']::TEXT[], '{}', '{}', ARRAY['Support community members in need','Reduce food waste','Build compassion and empathy','Make a tangible difference']::TEXT[], 1);
INSERT INTO kutumb_activities (title, image1, image2, description, schedule, participation_options, online_yoga, in_person_yoga, benefits, sort_order) VALUES ('Kutumb Bhajan Sandhya', 'bhajan.jpeg', NULL, 'Monthly Bhajan Sandhya and special knowledge sessions bringing the community together in a spiritual and positive environment.', 'First Saturday of every month, 7:00 PM - 10:00 PM', ARRAY['Attend as Guest','Perform Bhajan','Host at My Home']::TEXT[], '{}', '{}', ARRAY['Promote Indian culture','Promote mental health and well-being','Meet spiritually inclined people','Create positive impact in the community']::TEXT[], 2);
INSERT INTO kutumb_activities (title, image1, image2, description, schedule, participation_options, online_yoga, in_person_yoga, benefits, sort_order) VALUES ('Kutumb Men Shed', 'menshed.jpeg', NULL, 'Organise Men shed activities like long walk, chit-chat sessions, movie night, clean-ups and indoor-outdoor games.', 'Fortnightly on Saturdays, 4:00 PM - 9:00 PM', ARRAY['Long Walk','Chit-Chat Session','Movie Night','Clean-Up','Indoor Games','Outdoor Games']::TEXT[], '{}', '{}', ARRAY['Promote men''s mental health and well-being','Promote bond among members','Create positive impact in the community','Brainstorming for community betterment']::TEXT[], 3);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Seema Garg', 'President', '+61 432 716 406', 'seema@kutumb.org.au', 'Passionate community leader with over 30 years of experience in social impact initiatives. Dedicated to building inclusive communities and fostering positive change.', 'Seema.png', 0);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Raj Garg', 'Vice President', '+61 411 766 170', 'raj@kutumb.org.au', 'Experienced nonprofit professional committed to community wellness and engagement. Specializes in program development and volunteer coordination.', 'Raj.png', 1);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Ashok Gupta', 'Company Secretary and Principal Officer', '+61 412 830 048', 'ashok@kutumb.org.au', 'Detail-oriented administrator with a passion for organization excellence. Ensures smooth operations and effective communication within the organization.', 'Ashok.png', 2);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Naresh Kumar', 'Treasurer', '+61 xxx xxx xxx', 'naresh@kutumb.org.au', 'Financial professional dedicated to transparency and fiscal responsibility. Manages organizational finances with integrity and accountability.', 'Naresh.png', 3);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Suruchi Thapliyal', 'Coordinator, Event Performance', '+61 415 578 569', 'suruchi@kutumb.org.au', 'Creative event planner with expertise in community engagement. Designs and executes memorable events that bring people together.', 'Suruchi.png', 4);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Anil Mishra', 'Coordinator, Online Presence', '+61 466 713 166', 'anil@kutumb.org.au', 'A detail-oriented digital coordinator responsible for managing Kutumb''s online presence across platforms, ensuring consistent branding, engagement, and community outreach through effective digital communication.', 'Anil.png', 5);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Dr Vikas Kesarvani', 'Coordinator, Kutumb Men''s Shed', '+61 449 843 496', 'vikash@kutumb.org.au', 'Responsible for coordinating Kutumb''s Men''s Shed activities, organizing events that promote connection, wellbeing, and peer support among men in the community.', 'Vikas.png', 6);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Anjali Gupta', 'Committee Member', '+61 425 366 592', 'anjali@kutumb.org.au', 'Warm and welcoming membership coordinator focused on building strong relationships. Ensures every member feels valued and connected.', 'Anjali.png', 7);
INSERT INTO kutumb_team_profiles (name, role, phone, email, bio, image, sort_order) VALUES ('Pramodh Rai', 'Advisor', '+61 431 471 879', 'pramodh@kutumb.org.au', 'A highly experienced community leader and advisor with a strong background in social and cultural engagement. An active member of organisations such as the Indian Diaspora Council and Arya Samaj Association, bringing valuable insight and guidance to Kutumb''s mission.', 'Pramodh.png', 8);
